<script setup lang="ts">import type {Forecast} from '../../types';defineProps<{forecast:Forecast|null}>();const fmt=(n:number)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});</script>
<template><article class="panel signal-panel"><div class="panel-title"><span>TÍN HIỆU DỰ BÁO</span><span class="muted">{{forecast?`${forecast.progress}/${forecast.horizon} nến · ${forecast.status}`:'Chưa có dự báo'}}</span></div><div v-if="forecast" class="signal-empty"><span :class="forecast.signal.toLowerCase()" class="signal-direction">{{forecast.signal}}</span><b>Giá tham chiếu {{fmt(forecast.start_price)}} · dự báo {{forecast.horizon}} nến</b><small>{{forecast.metadata.confidenceLabel}} · {{forecast.metadata.neighbors}} mẫu tương đồng · Không phải xác suất đảm bảo.</small><small v-if="forecast.entry">Entry {{fmt(forecast.entry.low)}}–{{fmt(forecast.entry.high)}}　TP {{fmt(forecast.takeProfit||0)}}　SL {{fmt(forecast.stopLoss||0)}}</small></div><div v-else class="signal-empty"><span class="sparkle">✦</span><b>Sẵn sàng phân tích</b><small>Dự báo từ nến đã đóng và mẫu học cục bộ.</small></div></article></template>
